#!/usr/bin/env bash
set -euo pipefail

ROOT="/workspaces/advocate-mahbub-website"
cd "$ROOT"

STAMP="$(date +%Y-%m-%d-%H%M%S)"
BACKUP_DIR="backups/hissa-sprint-3c-metric-unicode-$STAMP"
mkdir -p "$BACKUP_DIR"

for f in \
  "src/pages/tools/hissa-calculator.astro" \
  "src/scripts/hissa-calculator.js" \
  "src/styles/hissa-calculator.css"
do
  [ -f "$f" ] && cp "$f" "$BACKUP_DIR/$(basename "$f")"
done

echo "Backup created: $BACKUP_DIR"

echo "" | base64 -d > /tmp/hissa-sprint-3c-patch.py
python3 /tmp/hissa-sprint-3c-patch.py
rm -f /tmp/hissa-sprint-3c-patch.py

echo
echo "Running Hissa tests..."
node --test tests/hissa/*.test.js

echo
echo "Running production build..."
npm run build

echo
echo "SUCCESS"
echo "Backup: $BACKUP_DIR"
echo
echo "Restart dev server if needed:"
echo "npm run dev -- --host 0.0.0.0"
echo
echo "Then test Normal, GroupLine, Metric, Bangla digits, and over-limit messages."
